           "type": "boolean"
          },
          "error": {
           "type": "string"
          },
          "hint": {
           "enum": [
            "day_month_swapped"
           ],
           "type": "string"
          },
          "ok": {
           "type": "boolean"
          },
          "verified": {
           "type": "boolean"
          },
